# -*- coding: utf-8 -*-
"""Build two offline real-engine ports from pinned vendor sources. Python 3.7+."""
from pathlib import Path
import json, shutil, subprocess, argparse
ROOT=Path(__file__).resolve().parents[1]
STYLE='''*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;font:14px system-ui,sans-serif;background:var(--bg,#f3f0e8);color:var(--ink,#242622)}canvas{display:block;touch-action:none}.controls{position:absolute;bottom:8px;left:8px;right:8px;display:flex;gap:6px;z-index:10}button,select{height:48px;min-width:0;padding:0 10px;background:var(--card,#f3f0e8);color:var(--ink,#242622);border:1px solid var(--line,#d5d3c8);border-radius:6px;font:14px system-ui,sans-serif}.controls>*{flex:1}.top{position:absolute;top:8px;left:12px;right:12px;z-index:10;pointer-events:none}.top strong{font-size:18px}.top p{margin:4px 0;font-size:12px}.status{position:absolute;bottom:64px;left:12px;right:12px;font-size:12px;pointer-events:none}.error{position:absolute;top:80px;left:12px;right:12px;background:var(--card,#f3f0e8);color:var(--action,#b53c28);padding:12px;display:none;z-index:11}'''

def finish(p,name,description,repo,source,icon):
    html=(p/'index.html').read_text()
    (p/'icon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">'+'<g transform="scale(1.3333333)">'+icon+'</g></svg>')
    (p/'bundle.json').write_text(json.dumps({'manifest':{'id':p.name,'name':name,'description':description,'entry':'index.html','layout':'fullscreen','theme_ui':'controls','icon':'icon.svg'},'files':{'index.html':html,'icon.svg':(p/'icon.svg').read_text()}},ensure_ascii=False,indent=2))
    (p/'UPSTREAM.txt').write_text('https://github.com/'+repo+'\nSHA '+(source/'ATOM_SHA').read_text()+'\nATOM adaptation: local controls, reduced complexity; upstream license retained.\n')
    shutil.copy(source/'LICENSE',p/'LICENSE')

def build():
    source=ROOT/'vendor/sculptgl-src';p=ROOT/'ports/clay-studio';p.mkdir(parents=True,exist_ok=True)
    shutil.copytree(source/'app',p,dirs_exist_ok=True)
    shutil.copytree(source/'src',p/'source',dirs_exist_ok=True)
    html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" crossorigin="anonymous" href="css/yagui.css"><style>'''+STYLE+'''#viewport{position:absolute!important;left:0!important;right:0!important;top:56px!important;bottom:78px!important;width:100%!important;height:calc(100% - 134px)!important}#canvas{width:100%;height:100%}.top *,.status{color:var(--ink,#242622)}</style><script>var NI=Image;window.Image=function(w,h){var i=new NI(w,h);i.crossOrigin='anonymous';return i};Image.prototype=NI.prototype;</script></head><body><div class="top"><strong>黏土工坊</strong><p>拖动雕刻 · 右键转动 · 滚轮缩放</p></div><div id="viewport"><canvas id="canvas"></canvas></div><div id="status" class="status">准备黏土</div><div id="error" class="error"></div><div class="controls"><button id="tool">堆土</button><button id="negative">凸起</button><button id="undo">撤销</button><button id="reset">重置</button></div><input id="fileopen" type="file" multiple hidden><input id="backgroundopen" type="file" hidden><input id="alphaopen" type="file" hidden><input id="textureopen" type="file" hidden><input id="matcapopen" type="file" hidden><script crossorigin="anonymous" src="sculptgl.js"></script><script crossorigin="anonymous" src="main.js"></script></body></html>'''
    (p/'index.html').write_text(html)
    (p/'main.js').write_text("""window.addEventListener('load',function(){try{var app=window.clayApp=new SculptGL();app.start();if(!app._gl)throw Error('需要WebGL支持');app._gui._guiMain.domMain.style.display='none';app.getSculptManager()._symmetry=false;app.onCanvasResize();var modes=[0,1,3],names=['堆土','膨胀','平滑'],index=0;function tool(){app.getSculptManager().setToolIndex(modes[index]);var t=app.getSculptManager().getCurrentTool();t._radius=30;t._intensity=.35;document.getElementById('tool').textContent=names[index]}function info(){document.getElementById('status').textContent=app.getMesh().getNbFaces()+' 面 · SculptGL真实雕刻 · 仅本次打开'}tool();info();document.getElementById('tool').onclick=function(){index=(index+1)%3;tool()};document.getElementById('negative').onclick=function(){var t=app.getSculptManager().getCurrentTool();t._negative=!t._negative;this.textContent=t._negative?'凹陷':'凸起'};document.getElementById('undo').onclick=function(){app.getStateManager().undo();app.render()};document.getElementById('reset').onclick=function(){app.clearScene();app.addSphere();tool();info()};window.addEventListener('resize',function(){app.onCanvasResize()})}catch(e){var box=document.getElementById('error');box.style.display='block';box.textContent=e.message}});""")
    finish(p,'黏土工坊','SculptGL真实雕刻 · 低面数离线','stephomi/sculptgl',source,'<path d="M12 35c-6-9-2-20 7-23 7-3 16 1 18 9 3 9-3 16-11 17-6 1-10-1-14-3Z"/><path d="m19 18 9 4-3 10m-11-6 8 1"/>')
    source=ROOT/'vendor/jscad-src';p=ROOT/'ports/parametric-maker';p.mkdir(parents=True,exist_ok=True)
    shutil.copytree(source/'packages/modeling',p/'source-modeling',ignore=shutil.ignore_patterns('node_modules'),dirs_exist_ok=True)
    shutil.copy(source/'packages/modeling/dist/jscad-modeling.min.js',p/'jscad-modeling.min.js')
    for f in ['three.min.js','OrbitControls.js']:shutil.copy(ROOT/'ports/model-viewer'/f,p/f)
    shutil.copy(ROOT/'ports/model-viewer/LICENSE',p/'THREE-LICENSE')
    (p/'index.html').write_text('''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'''+STYLE+'''#scene{width:100%;height:100%}.parameter{position:absolute;top:56px;left:12px;width:140px;z-index:10;background:var(--card,#f3f0e8);color:var(--ink,#242622);padding:8px;font-size:12px}.parameter input{width:100%;height:36px}label{display:block}</style></head><body><div class="top"><strong>参数造物</strong><p>拖动旋转 · JSCAD布尔建模 · 单位mm</p></div><div id="scene"></div><div class="parameter"><label>尺寸 <span id="size-label">40</span><input id="size" type="range" min="24" max="64" value="40" step="4"></label><label>壁厚 <span id="wall-label">3</span><input id="wall" type="range" min="2" max="6" value="3" step="1"></label></div><div id="status" class="status"></div><div id="error" class="error"></div><div class="controls"><select id="preset"><option value="box">开口盒</option><option value="bracket">直角支架</option><option value="ring">圆孔底座</option></select><button id="rebuild">生成</button><button id="wire">线框</button><button id="fit">归位</button></div><script crossorigin="anonymous" src="jscad-modeling.min.js"></script><script crossorigin="anonymous" src="three.min.js"></script><script crossorigin="anonymous" src="OrbitControls.js"></script><script crossorigin="anonymous" src="main.js"></script></body></html>''')
    (p/'main.js').write_text(JSCAD_JS)
    finish(p,'参数造物','JSCAD真实布尔建模 · 盒子支架底座','jscad/OpenJSCAD.org',source,'<path d="m8 15 16-8 16 8v19l-16 8-16-8Z"/><path d="m8 15 16 9 16-9M24 24v18"/><path d="m16 11 16 9v11"/>')

JSCAD_JS=r'''(function(){try{var m=jscadModeling,renderer=new THREE.WebGLRenderer({antialias:false});renderer.setPixelRatio(1);renderer.setSize(innerWidth,innerHeight);renderer.setClearColor(0xe4e4df);document.getElementById('scene').appendChild(renderer.domElement);var scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(40,innerWidth/innerHeight,.1,2000);camera.up.set(0,0,1);var controls=new THREE.OrbitControls(camera,renderer.domElement);controls.enableDamping=true;scene.add(new THREE.HemisphereLight(0xffffff,0x555555,1));var light=new THREE.DirectionalLight(0xffffff,.7);light.position.set(20,-40,80);scene.add(light);var model,wire=false,last;function generate(){var s=Number(document.getElementById('size').value),w=Number(document.getElementById('wall').value),p=document.getElementById('preset').value;var cube=m.primitives.cuboid,cyl=m.primitives.cylinder,sub=m.booleans.subtract,uni=m.booleans.union;if(p==='box')last=sub(cube({size:[s,s,s*.6]}),cube({size:[s-2*w,s-2*w,s*.6],center:[0,0,w]}));else if(p==='bracket'){var solid=uni(cube({size:[s,s,w],center:[0,0,w/2]}),cube({size:[w,s,s*.7],center:[-s/2+w/2,0,s*.35]}));last=sub(solid,cyl({radius:3,height:w*3,segments:24,center:[s*.2,0,w/2]}))}else last=sub(cyl({radius:s/2,height:w*2,segments:32}),cyl({radius:s*.2,height:w*3,segments:32}));var points=[];m.geometries.geom3.toPolygons(last).forEach(function(poly){var v=poly.vertices;for(var i=1;i<v.length-1;i++)[v[0],v[i],v[i+1]].forEach(function(pt){points.push(pt[0],pt[1],pt[2])})});if(model){scene.remove(model);model.geometry.dispose();model.material.dispose()}var geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(points,3));geo.computeVertexNormals();model=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:0xdf5038,roughness:.75,metalness:0,wireframe:wire}));scene.add(model);window.parametricModel=last;document.getElementById('status').textContent=(points.length/9)+' 三角面 · 尺寸 '+s+'mm · 实体CSG';fit()}function fit(){var box=new THREE.Box3().setFromObject(model),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()).length();controls.target.copy(center);camera.position.copy(center).add(new THREE.Vector3(size*.95,-size*1.2,size*.85));camera.lookAt(center);controls.update()}['size','wall'].forEach(function(id){document.getElementById(id).oninput=function(){document.getElementById(id+'-label').textContent=this.value}});document.getElementById('rebuild').onclick=generate;document.getElementById('preset').onchange=generate;document.getElementById('wire').onclick=function(){wire=!wire;model.material.wireframe=wire;this.textContent=wire?'实体':'线框'};document.getElementById('fit').onclick=fit;function tick(){controls.update();renderer.render(scene,camera);requestAnimationFrame(tick)}generate();tick();window.addEventListener('resize',function(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()});window.addEventListener('pagehide',function(){controls.dispose();renderer.dispose()})}catch(e){document.getElementById('error').style.display='block';document.getElementById('error').textContent=e.message}})();'''
if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--compile',action='store_true',help='Rebuild SculptGL using installed pnpm/webpack dependencies')
    args=parser.parse_args()
    if args.compile:
        source=ROOT/'vendor/sculptgl-src'
        file=source/'src/Scene.js'
        file.write_text(file.read_text().replace('mesh.getNbFaces() < 50000','mesh.getNbFaces() < 2500'))
        subprocess.check_call(['pnpm','exec','webpack','--env','release'],cwd=str(source))
    build()
